<?php
declare(strict_types=1); require dirname(__DIR__).'/workflow-core.php'; trackingHeaders();
if(($_SERVER['REMOTE_USER']??'')!=='aor-project-admin'){http_response_code(403);exit('Project admin is locked.');}
$sessionDirectory=trackingDirectory().DIRECTORY_SEPARATOR.'sessions';if(!is_dir($sessionDirectory))mkdir($sessionDirectory,0700,true);session_save_path($sessionDirectory);session_name('AOR_PROJECT_ADMIN');session_start();$_SESSION['csrf']??=bin2hex(random_bytes(32));
