$message='';$error='';
try{if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??'')))throw new InvalidArgumentException('This form expired.');trackingLocked(function(){
    $settings=workflowDefaults();foreach(array_keys($settings) as $key)$settings[$key]=workflowText($_POST[$key]??'',4000);workflowWrite('.settings.json',$settings);
    $templates=[];foreach(['web'=>'Website Development and Care','creative'=>'Creative Design and Video','pr'=>'PR, Writing and Communications'] as $key=>$name){$templates[$key]=['name'=>$name,'scope'=>workflowText($_POST['template_scope'][$key]??'',6000),'items'=>[['description'=>workflowText($_POST['template_description'][$key]??'',300),'quantity'=>1,'unit_price'=>number_format(workflowMoney($_POST['template_price'][$key]??'0')/100,2,'.','')]]];}workflowWrite('.templates.json',$templates);
});$message='Defaults and service templates saved.';}}
catch(Throwable $x){$error=$x->getMessage();}
