?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Workflow settings | AOR</title><link rel="stylesheet" href="../tracking.css"><link rel="stylesheet" href="admin.css"><link rel="stylesheet" href="workflow.css"></head><body><main><p class="eyebrow">AOR · Private settings</p><h1>Defaults and templates</h1><p><a href="./">← Project workspace</a></p><?php if($message):?><p class="notice"><?=e($message)?></p><?php endif?><?php if($error):?><p class="notice error"><?=e($error)?></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><section><h2>Business and payment defaults</h2><p>These values pre-fill new project invoices. Editing a project later does not change these defaults.</p><div class="form-grid"><label>Business name<input name="business_name" value="<?=e($settings['business_name'])?>"></label><label>Business email<input name="business_email" type="email" value="<?=e($settings['business_email'])?>"></label></div><label>Business address<textarea name="business_address"><?=e($settings['business_address'])?></textarea></label><label>Wise details<textarea name="wise"><?=e($settings['wise'])?></textarea></label><label>PayPal details<textarea name="paypal"><?=e($settings['paypal'])?></textarea></label><label>Other payment details<textarea name="other_payment"><?=e($settings['other_payment'])?></textarea></label><label>Terms reference<input name="terms_reference" value="<?=e($settings['terms_reference'])?>"></label></section><section><h2>Service proposal templates</h2><?php foreach($templates as $key=>$template):?><article><h3><?=e($template['name'])?></h3><label>Scope<textarea name="template_scope[<?=e($key)?>]" rows="3"><?=e($template['scope'])?></textarea></label><div class="form-grid"><label>Default line item<input name="template_description[<?=e($key)?>]" value="<?=e($template['items'][0]['description']??'')?>"></label><label>Default unit price<input name="template_price[<?=e($key)?>]" value="<?=e($template['items'][0]['unit_price']??'0')?>"></label></div></article><?php endforeach?></section><button>Save defaults and templates</button></form></main></body></html>
